def-hyp(
    list-partial(
        Type.judge(@x, X@Topology.ctxt.X),
        Type.judge(@y, Y@Topology.ctxt.Y),
        Type.judge(@f, Type.to(X@Topology.ctxt.X, Y@Topology.ctxt.Y)),
        Type.judge(@τ_X, Set(Set(X@Topology.ctxt.X))),
        Type.judge(@τ_Y, Set(Set(Y@Topology.ctxt.Y))),
        Type.judge(@x_0, X@Topology.ctxt.X)
    ),
    Topology.mapLimit(x, x_0, f, y),
    Logic.forall-typed(
        @V,
        Set(Y@Topology.ctxt.Y),
        Logic.implies(
            Set.mem(V, τ_Y),
            Logic.and(
                Set.mem(y, V),
                Logic.exists-typed(
                    @U,
                    Set(X@Topology.ctxt.X),
                    Logic.and(
                        Topology.deletedNeighborhood(U, x_0),
                        Set.subset(
                            Set.fun(f, U),
                            V
                        )
                    )
                )
            )
        )
    )
)
